//! Benchmarks for s2n-tls handshakes with additional KX/sig combinations that
//! are not supported by all TLS implementations (e.g. ML-KEM, ML-DSA).
//!
//! All scenarios use a depth-2 cert chain (leaf → CA) to match a realistic
//! deployment configuration. Certs are generated by `cargo run --bin generate-certs`.
//!
//! Benchmarked scenarios:
//! - kx: secp256r1,  sig: ecdsa-p256
//! - kx: secp384r1,  sig: ecdsa-p384
//! - kx: mlkem1024,  sig: ecdsa-p384
//! - kx: mlkem1024,  sig: mldsa44
//! - kx: mlkem1024,  sig: mldsa87

use criterion::{criterion_group, criterion_main, BatchSize, BenchmarkId, Criterion};
use s2n_tls::{
    callbacks::VerifyHostNameCallback,
    config::Builder,
    enums::{ClientAuthType, Mode},
    security::Policy,
};
use tls_harness::{
    cohort::{self, S2NConnection},
    harness::TlsInfo,
    TlsConnPair,
};

/// Load a cert file from the generated certs directory.
macro_rules! load_cert {
    ($dir:expr, $file:expr) => {
        include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"), "/certs/", $dir, "/", $file))
    };
}

const ECDSA_P256_CHAIN: &[u8] = load_cert!("ecdsa_p256", "server-chain.pem");
const ECDSA_P256_KEY: &[u8] = load_cert!("ecdsa_p256", "server-key.pem");
const ECDSA_P256_CA: &[u8] = load_cert!("ecdsa_p256", "ca-cert.pem");

const ECDSA_P384_CHAIN: &[u8] = load_cert!("ecdsa_p384", "server-chain.pem");
const ECDSA_P384_KEY: &[u8] = load_cert!("ecdsa_p384", "server-key.pem");
const ECDSA_P384_CA: &[u8] = load_cert!("ecdsa_p384", "ca-cert.pem");

const MLDSA44_CHAIN: &[u8] = load_cert!("mldsa44", "server-chain.pem");
const MLDSA44_KEY: &[u8] = load_cert!("mldsa44", "server-key.pem");
const MLDSA44_CA: &[u8] = load_cert!("mldsa44", "ca-cert.pem");

const MLDSA87_CHAIN: &[u8] = load_cert!("mldsa87", "server-chain.pem");
const MLDSA87_KEY: &[u8] = load_cert!("mldsa87", "server-key.pem");
const MLDSA87_CA: &[u8] = load_cert!("mldsa87", "ca-cert.pem");

/// Each benchmark scenario specifies a security policy, the server cert chain/key,
/// and the trust anchor (CA cert).
struct Scenario {
    name: &'static str,
    /// s2n-tls security policy version string
    policy: &'static str,
    server_chain: &'static [u8],
    server_key: &'static [u8],
    ca_cert: &'static [u8],
}

/// Verify "localhost" — all generated certs have SAN=localhost.
struct LocalhostVerify;
impl VerifyHostNameCallback for LocalhostVerify {
    fn verify_host_name(&self, hostname: &str) -> bool {
        hostname == "localhost"
    }
}

const SCENARIOS: &[Scenario] = &[
    Scenario {
        name: "secp256r1+ecdsa_p256",
        // 20251014 (aka "default"): TLS1.2+, prefers secp256r1, supports ECDSA
        policy: "20251014",
        server_chain: ECDSA_P256_CHAIN,
        server_key: ECDSA_P256_KEY,
        ca_cert: ECDSA_P256_CA,
    },
    Scenario {
        name: "secp384r1+ecdsa_p384",
        // 20250414: TLS1.3, ecc_preferences with only secp384r1, supports ECDSA
        policy: "20250414",
        server_chain: ECDSA_P384_CHAIN,
        server_key: ECDSA_P384_KEY,
        ca_cert: ECDSA_P384_CA,
    },
    Scenario {
        name: "mlkem1024+ecdsa_p384",
        // 20260513: TLS1.3, pure MLKEM1024, supports ECDSA + ML-DSA-87
        policy: "20260513",
        server_chain: ECDSA_P384_CHAIN,
        server_key: ECDSA_P384_KEY,
        ca_cert: ECDSA_P384_CA,
    },
    Scenario {
        name: "mlkem1024+mldsa44",
        // test_all: supports all KEM groups (including pure MLKEM1024) and all
        // signature schemes (including ML-DSA-44).
        policy: "test_all",
        server_chain: MLDSA44_CHAIN,
        server_key: MLDSA44_KEY,
        ca_cert: MLDSA44_CA,
    },
    Scenario {
        name: "mlkem1024+mldsa87",
        // 20260513: TLS1.3, pure MLKEM1024 + ML-DSA-87
        policy: "20260513",
        server_chain: MLDSA87_CHAIN,
        server_key: MLDSA87_KEY,
        ca_cert: MLDSA87_CA,
    },
];

fn build_config(scenario: &Scenario, mode: Mode) -> cohort::S2NConfig {
    let mut builder = Builder::new();
    builder
        .set_security_policy(&Policy::from_version(scenario.policy).unwrap())
        .unwrap()
        .with_system_certs(false)
        .unwrap()
        .set_client_auth_type(ClientAuthType::None)
        .unwrap();

    match mode {
        Mode::Client => {
            builder.trust_pem(scenario.ca_cert).unwrap();
            builder
                .set_verify_host_callback(LocalhostVerify)
                .unwrap();
        }
        Mode::Server => {
            builder
                .load_pem(scenario.server_chain, scenario.server_key)
                .unwrap();
        }
    }

    cohort::S2NConfig {
        config: builder.build().unwrap(),
        ticket_storage: Default::default(),
    }
}

fn bench_s2n_tls_handshakes(c: &mut Criterion) {
    let mut group = c.benchmark_group("handshake-s2n-tls");

    for scenario in SCENARIOS {
        let client_config = build_config(scenario, Mode::Client);
        let server_config = build_config(scenario, Mode::Server);

        group.bench_function(BenchmarkId::new("s2n-tls", scenario.name), |b| {
            b.iter_batched_ref(
                || {
                    TlsConnPair::<S2NConnection, S2NConnection>::from_configs(
                        &client_config,
                        &server_config,
                    )
                },
                |conn_pair| {
                    conn_pair.handshake().unwrap();
                    assert!(!conn_pair.server.resumed_connection());
                },
                BatchSize::PerIteration,
            )
        });
    }

    group.finish();
}

criterion_group!(benches, bench_s2n_tls_handshakes);
criterion_main!(benches);
